// Generated by tools/convert_dx.js from the diagnosis-practice-case study data (DSM-5-TR differential tables,
// condensed). Do not edit by hand. Used by the STUDY CASES encounters (src/game/dxcases.js).
G.DX_TABLES = [{"roll":1,"id":"3.1.1","name":"Intellectual Developmental Disorder","group":"Neurodevelopmental Disorders","core":"Global deficits in reasoning, problem solving, and learning, plus deficits in adaptive function. Onset in the developmental period.","diffs":[["Specific Learning Disorder","deficit in one academic area only. Intellect and adaptive function are normal."],["Communication Disorders","deficit in speech or language only. Intellect and adaptive function are normal."],["Autism Spectrum Disorder","social communication deficit is larger than the general intellectual level. Restricted, repetitive behaviors are present."],["Major Neurocognitive Disorder","a decline from a previous higher level."],["Borderline intellectual functioning","milder deficit (IQ near 70), or no adaptive deficit."]]},
{"roll":2,"id":"3.1.2","name":"Communication Disorders","group":"Neurodevelopmental Disorders","members":["Language Disorder","Speech Sound Disorder","Childhood-Onset Fluency Disorder","Social (Pragmatic) Communication Disorder"],"core":"Impairment limited to speech, language, or the social use of language. The problem is the same in all settings.","diffs":[["Intellectual Developmental Disorder","global intellectual impairment."],["Hearing loss, neurological, motor, or structural cause (for example, cleft palate, dysarthria)","the physical cause fully explains the deficit."],["Selective Mutism","the child speaks normally in safe settings, such as home."],["Tourette's Disorder (only vs. Fluency Disorder)","vocal tics differ in form and timing from stuttered speech."],["Autism Spectrum Disorder (only vs. Social Pragmatic)","restricted, repetitive behaviors are present."],["Social Anxiety Disorder (only vs. Social Pragmatic)","the skills exist, but anxiety prevents their use."],["Normal developmental dysfluency or articulation errors","appropriate for age."]]},
{"roll":3,"id":"3.1.3","name":"Autism Spectrum Disorder","group":"Neurodevelopmental Disorders","core":"Social communication and interaction deficits in many settings, plus restricted, repetitive behaviors or interests. Present from early development.","diffs":[["Schizophrenia (childhood onset)","normal early development, then hallucinations or delusions."],["Selective Mutism","normal early development. Normal communication in safe settings."],["Language Disorder","no qualitative social impairment. Interests are not restricted."],["Social (Pragmatic) Communication Disorder","no restricted, repetitive behaviors."],["Intellectual Developmental Disorder","social skills match the general intellectual level."],["Stereotypic Movement Disorder","social interaction and language are normal."]]},
{"roll":4,"id":"3.1.4","name":"Attention-Deficit/Hyperactivity Disorder","group":"Neurodevelopmental Disorders","core":"Inattention and/or hyperactivity-impulsivity above the developmental level. Onset before age 12. Present in two or more settings.","diffs":[["Normal active child","behavior fits the developmental level."],["Understimulating environment","inattention comes from boredom."],["Oppositional Defiant Disorder","the child refuses tasks from defiance, not from difficulty with sustained effort."],["Intermittent Explosive Disorder","episodes of serious aggression toward others."],["Conduct Disorder","a pattern of antisocial behavior."],["Stereotypic Movement Disorder","fixed, repetitive movements, not general restlessness."],["Specific Learning Disorder","inattention occurs only during schoolwork."],["Intellectual Developmental Disorder","symptoms occur only with academic tasks above the mental age."],["Autism Spectrum Disorder","withdrawal comes from social communication deficits. Tantrums come from changes in routine."],["Disinhibited Social Engagement Disorder","social disinhibition after severe neglect, without the full ADHD cluster."],["Disruptive Mood Dysregulation Disorder","persistent irritability between outbursts."],["Anxiety Disorders","inattention comes from worry and rumination."],["Major Depressive Disorder","poor concentration only during depressive episodes."],["Bipolar I or II Disorder","episodic symptoms with elevated mood, grandiosity, and less need for sleep."],["Borderline, Antisocial, or Narcissistic Personality Disorder","self-injury, antisocial acts, fear of abandonment, or lack of empathy."],["Medication-induced symptoms","symptoms start with a medication and stop after it stops."],["Neurocognitive Disorders","later onset."]]},
{"roll":5,"id":"3.1.5","name":"Specific Learning Disorder","group":"Neurodevelopmental Disorders","core":"Persistent difficulty in reading, spelling, writing, or math, well below the expected level for age. Onset in school years. Not explained by intellectual disability or sensory loss.","diffs":[["Normal variation in academic attainment","no significant impairment, skills are not well below the age level, or the difficulty stops with targeted help."]]},
{"roll":6,"id":"3.1.6","name":"Tic Disorders","group":"Neurodevelopmental Disorders","members":["Tourette's Disorder (motor and vocal tics, more than 1 year)","Persistent Motor or Vocal Tic Disorder (one type, more than 1 year)","Provisional Tic Disorder (less than 1 year). Onset before age 18"],"core":"Sudden, rapid, recurrent, nonrhythmic movements or vocalizations.","diffs":[["Chorea","random, continuous, irregular movements of the whole body."],["Dystonia","sustained contraction of opposing muscles. Twisted posture."],["Myoclonus","very fast, not suppressible, no urge before the movement."],["Substance- or medication-induced tics","tics start with a stimulant and stop after it stops."],["Stereotypies (Stereotypic Movement Disorder or Autism Spectrum Disorder)","rhythmic, driven, and more complex."],["OCD compulsions","done in response to an obsession or to rigid rules."],["Schizophrenia","odd behavior with delusions, negative symptoms, and a decline in function."]]},
{"roll":7,"id":"3.2.1","name":"Schizophrenia or Schizophreniform Disorder","group":"Schizophrenia Spectrum and Other Psychotic Disorders","members":["Schizophrenia (6 months or more)","Schizophreniform Disorder (1 to 6 months)"],"core":"Two or more of delusions, hallucinations, disorganized speech, disorganized or catatonic behavior, and negative symptoms. At least one is one of the first three. At least 1 month of active phase.","diffs":[["Psychotic Disorder, Delirium, or Neurocognitive Disorder due to a medical condition","a medical cause explains the symptoms."],["Substance/medication-induced disorder","a substance starts and maintains the symptoms."],["Schizoaffective Disorder","mood episodes are present for the majority of the illness."],["Major Depressive or Bipolar Disorder with psychotic features","psychosis occurs only during mood episodes."],["Brief Psychotic Disorder","total duration from 1 day to less than 1 month."],["Delusional Disorder","delusions only, without other active-phase symptoms."],["PTSD","flashbacks and hypervigilance after a traumatic event."],["Autism Spectrum Disorder","early onset. No prominent delusions or hallucinations."],["Schizotypal, Schizoid, or Paranoid Personality Disorder","mild, lifelong traits below the psychotic threshold."]]},
{"roll":8,"id":"3.2.2","name":"Schizoaffective Disorder","group":"Schizophrenia Spectrum and Other Psychotic Disorders","core":"A major mood episode at the same time as active-phase schizophrenia symptoms. Also 2 weeks or more of delusions or hallucinations without a mood episode. Mood episodes are present for the majority of the illness.","diffs":[["Medical condition","a medical cause explains the symptoms."],["Substance/medication","a substance explains the symptoms."],["Schizophrenia","no mood episodes, or mood episodes for only a minority of the illness."],["Bipolar or Major Depressive Disorder with psychotic features","psychosis occurs only during mood episodes."],["Delusional Disorder","delusions for 1 month or more, and active-phase criteria are never met."]]},
{"roll":9,"id":"3.2.3","name":"Delusional Disorder","group":"Schizophrenia Spectrum and Other Psychotic Disorders","core":"One or more delusions for 1 month or more. Active-phase criteria for schizophrenia are never met. Function is not markedly impaired apart from the delusion.","diffs":[["Medical condition","a medical cause explains the delusions."],["Substance/medication","a substance explains the delusions."],["Schizophrenia or Schizophreniform Disorder","at least one period of full active-phase symptoms."],["Bipolar or Major Depressive Disorder with psychotic features","delusions occur only during mood episodes."],["Brief Psychotic Disorder","less than 1 month."],["OCD with absent insight","the fixed belief is part of obsessions and compulsions."],["Body Dysmorphic Disorder with absent insight","the fixed belief is about a defect in appearance."],["Paranoid or Schizotypal Personality Disorder","suspicion is not of delusional intensity."]]},
{"roll":10,"id":"3.2.4","name":"Brief Psychotic Disorder","group":"Schizophrenia Spectrum and Other Psychotic Disorders","core":"One or more of delusions, hallucinations, disorganized speech, or disorganized or catatonic behavior. Duration from 1 day to less than 1 month. Full return to the previous level.","diffs":[["Medical condition","a medical cause explains the symptoms."],["Substance/medication","a substance explains the symptoms."],["Mood disorder with psychotic features","psychosis occurs only during mood episodes."],["Schizophreniform Disorder, Schizophrenia, or Delusional Disorder","symptoms last 1 month or more."],["Transient psychotic symptoms in a personality disorder (for example, Borderline)","usually less than 1 day."]]},
{"roll":11,"id":"3.2.5","name":"Unspecified Catatonia","group":"Schizophrenia Spectrum and Other Psychotic Disorders","core":"Clinically significant catatonic symptoms. The cause is unclear, or the full criteria are not met.","diffs":[["Catatonic Disorder Due to Another Medical Condition","full syndrome with a known neurological or metabolic cause."],["Delirium","catatonic signs occur only with a disturbance of attention and awareness."],["Medication-induced movement disorder (including neuroleptic malignant syndrome)","a dopamine-blocking medication explains the rigidity or akinesia."],["Catatonia with a psychotic disorder","other psychotic symptoms are present."],["Catatonia with a mood disorder","occurs only during mood episodes."],["Catatonia with Autism Spectrum Disorder","autism features are present."]]},
{"roll":12,"id":"3.3.1","name":"Bipolar I Disorder","group":"Bipolar and Related Disorders","core":"At least one Manic Episode (1 week or more, or any duration with hospitalization).","diffs":[["Bipolar Disorder Due to Another Medical Condition","a medical cause explains all manic episodes."],["Substance/medication-induced","symptoms occur only with the substance. A full mania that continues after the antidepressant effect still counts as Bipolar I."],["Major Depressive Disorder","never manic or hypomanic."],["Bipolar II Disorder","hypomania and major depression, but never mania."],["Cyclothymic Disorder","highs and lows below the full episode threshold."],["Schizophrenia, Delusional, or Schizophreniform Disorder","psychosis occurs outside mood episodes."],["Schizoaffective Disorder","psychosis for 2 weeks or more without a mood episode."],["ADHD","persistent, onset before age 12, not episodic."],["Disruptive Mood Dysregulation Disorder","chronic irritability, not distinct episodes."],["Borderline Personality Disorder","persistent mood lability since early adulthood, not episodic."]]},
{"roll":13,"id":"3.3.2","name":"Bipolar II Disorder","group":"Bipolar and Related Disorders","core":"At least one Hypomanic Episode (4 days or more) and at least one Major Depressive Episode. Never a Manic Episode.","diffs":[["Medical condition","a medical cause explains the episodes."],["Substance/medication","a substance explains the episodes."],["Major Depressive Disorder","no hypomania."],["Bipolar I Disorder","at least one manic episode."],["Cyclothymic Disorder","no full hypomanic or depressive episode."],["Schizophrenia, Delusional, or Schizophreniform Disorder","psychosis occurs outside mood episodes."],["Schizoaffective Disorder","psychosis for 2 weeks or more without a mood episode."],["ADHD","persistent, onset before age 12, not episodic."],["Disruptive Mood Dysregulation Disorder","chronic irritability, not episodes of 4 days or more."],["Borderline Personality Disorder","persistent lability since early adulthood."]]},
{"roll":14,"id":"3.3.3","name":"Cyclothymic Disorder","group":"Bipolar and Related Disorders","core":"For 2 years or more (1 year in youth), many periods of hypomanic symptoms and depressive symptoms. Full episode criteria are never met.","diffs":[["Bipolar I or II Disorder with rapid cycling","full mood episodes are present."],["Borderline Personality Disorder","identity disturbance and self-harm are also present."],["Medical condition","a medical cause explains the mood symptoms."],["Substance/medication","a substance explains the mood symptoms."]]},
{"roll":15,"id":"3.4.1","name":"Major Depressive Disorder","group":"Depressive Disorders","core":"2 weeks or more of depressed mood or loss of interest, with five or more symptoms in total.","diffs":[["Bipolar I or II Disorder","any manic or hypomanic episode."],["Depressive Disorder Due to Another Medical Condition","a medical cause (for example, hypothyroidism) explains the episodes."],["Substance/medication-induced","a substance explains the episodes."],["Persistent Depressive Disorder","depressed mood more days than not for 2 years or more."],["Premenstrual Dysphoric Disorder","symptoms are linked to the week before menses and stop after menses."],["Disruptive Mood Dysregulation Disorder","chronic irritability outside mood episodes."],["Schizophrenia, Delusional, or Schizophreniform Disorder","psychosis occurs outside mood episodes."],["Schizoaffective Disorder","psychosis for 2 weeks or more without a mood episode."],["Neurocognitive Disorder with mood symptoms","cognitive decline from a medical or substance cause."],["Adjustment Disorder with depressed mood","response to a stressor that does not meet episode criteria."],["Prolonged Grief Disorder","yearning for the deceased, 12 months or more after the death."],["Bereavement","grief comes in waves linked to reminders of the deceased."],["Normal sadness","short, few symptoms, no impairment."]]},
{"roll":16,"id":"3.4.2","name":"Persistent Depressive Disorder","group":"Depressive Disorders","core":"Depressed mood more days than not for 2 years or more (1 year in youth), with two or more other symptoms.","diffs":[["Major Depressive Disorder","five or more symptoms nearly every day for 2 weeks."],["Chronic psychotic disorder","depressed mood occurs only during the psychotic disorder."],["Medical condition","a chronic medical cause explains the symptoms."],["Substance/medication","chronic substance use explains the symptoms."],["Bipolar I or II Disorder","any manic or hypomanic episode."],["Cyclothymic Disorder","hypomanic periods are present."],["Personality Disorder","an enduring pattern from adolescence. Both can be present."]]},
{"roll":17,"id":"3.4.3","name":"Premenstrual Dysphoric Disorder","group":"Depressive Disorders","core":"Five or more symptoms, with at least one mood symptom, in the final week before menses. Symptoms improve after menses start and are minimal in the week after. Daily ratings over two or more cycles confirm the pattern.","diffs":[["Premenstrual syndrome","fewer than five symptoms. No mood symptom is necessary."],["Dysmenorrhea","pain that starts with menses."],["Medical condition","a medical cause (for example, thyroid disease) explains the symptoms."],["Hormone-induced","symptoms start with hormonal treatment and stop after it stops."],["Bipolar or Major Depressive Disorder","episodes are not linked to the cycle."],["Premenstrual worsening of another disorder","symptoms continue after menses."]]},
{"roll":18,"id":"3.4.4","name":"Disruptive Mood Dysregulation Disorder","group":"Depressive Disorders","core":"Severe temper outbursts three or more times per week, with persistent irritable mood between outbursts. 12 months or more. Onset before age 10. First diagnosis from age 6 to 18.","diffs":[["Medical condition","a medical cause explains the symptoms."],["Substance/medication","a substance explains the symptoms."],["Bipolar I or II Disorder","distinct episodes with more energy and less need for sleep."],["Oppositional Defiant Disorder","less severe, without persistent mood disruption."],["Major Depressive Disorder","irritability occurs only during depressive episodes."],["Anxiety Disorders","irritability occurs only in anxiety-provoking situations."],["Autism Spectrum Disorder","outbursts come from changes in routine."],["Intermittent Explosive Disorder","no persistent irritable mood between outbursts."]]},
{"roll":19,"id":"3.5.1","name":"Separation Anxiety Disorder","group":"Anxiety Disorders","core":"Excessive fear about separation from attachment figures. 4 weeks or more in youth, usually 6 months or more in adults.","diffs":[["Generalized Anxiety Disorder","many worries, not only separation."],["Panic Disorder","unexpected panic attacks."],["Agoraphobia","fear of being trapped without help."],["PTSD","reexperiencing of a traumatic event."],["Prolonged Grief Disorder","distress about separation from a deceased person."],["Social Anxiety Disorder","school refusal from fear of judgment."],["Illness Anxiety Disorder","focus on having the disease itself."],["Conduct Disorder","truancy, and the child stays away from home."],["Oppositional Defiant Disorder","opposition not related to separation."],["Depressive disorders","the person stays home from low interest or fatigue."],["Dependent Personality Disorder","reliance on anyone, not on specific attachment figures."],["Borderline Personality Disorder","identity problems and impulsivity are also present."],["Normal developmental separation anxiety","appropriate for age (for example, near age 1)."]]},
{"roll":20,"id":"3.5.2","name":"Selective Mutism","group":"Anxiety Disorders","core":"Consistent failure to speak in specific social situations, with normal speech in others. 1 month or more, not the first month of school.","diffs":[["Communication Disorders","the problem is the same in all settings."],["Autism Spectrum Disorder","speech difficulty also occurs with family."],["Social Anxiety Disorder","fear also occurs in situations without speech. Both can be present."]]},
{"roll":21,"id":"3.5.3","name":"Specific Phobia","group":"Anxiety Disorders","core":"Marked fear of a specific object or situation, 6 months or more. Subtypes: Animal, Natural Environment, Blood-Injection-Injury, Situational, Other.","diffs":[["Agoraphobia","fear in two or more agoraphobic clusters."],["Social Anxiety Disorder","fear only of social situations."],["PTSD or Acute Stress Disorder","fear only of trauma reminders."],["OCD","avoidance prevents an obsession."],["Separation Anxiety Disorder","fear of separation from attachment figures."],["Psychotic disorder","avoidance comes from a delusion."],["Eating disorders","avoidance of food only."],["Normal avoidance","realistic danger, or no impairment."],["Transient childhood fears","less than 6 months."]]},
{"roll":22,"id":"3.5.4","name":"Social Anxiety Disorder","group":"Anxiety Disorders","core":"Marked fear of scrutiny in social situations, 6 months or more.","diffs":[["Panic Disorder","unexpected panic attacks."],["Agoraphobia","fear of being trapped without help."],["Generalized Anxiety Disorder","worries also about nonsocial matters."],["Specific Phobia","embarrassment only about the reaction to the phobic object."],["Separation Anxiety Disorder","comfortable when the attachment figure is present."],["Selective Mutism","no fear in social situations without speech."],["Oppositional Defiant Disorder","refusal to speak from defiance."],["Autism Spectrum Disorder","lack of age-appropriate social relationships."],["Avoidant Personality Disorder","both can be present."],["Major Depressive Disorder","low self-esteem also outside social situations."],["Body Dysmorphic Disorder","fear only about an appearance defect."],["Delusional Disorder","belief about an odor or defect held with delusional intensity."],["Medical condition (for example, tremor, rosacea)","the fear is proportionate."],["Other disorder (for example, eating disorder, schizophrenia)","social anxiety occurs only as part of it."],["Normal shyness","no impairment."]]},
{"roll":23,"id":"3.5.5","name":"Panic Disorder","group":"Anxiety Disorders","core":"Recurrent unexpected panic attacks, then 1 month or more of worry or change in behavior.","diffs":[["Anxiety Disorder Due to Another Medical Condition","a medical cause (for example, hyperthyroidism) explains the attacks."],["Substance/medication-induced","a substance explains the attacks."],["Panic attacks in another disorder","attacks are cued by that disorder's situations."],["Extreme danger","the attack has an obvious cause."],["Isolated panic attack","only one attack."],["Limited-symptom attacks","fewer than four symptoms."]]},
{"roll":24,"id":"3.5.6","name":"Agoraphobia","group":"Anxiety Disorders","core":"Fear in two or more of five situations (public transport, open spaces, enclosed places, crowds or lines, outside home alone), because escape or help is difficult. 6 months or more.","diffs":[["Social Anxiety Disorder","fear of scrutiny."],["Specific Phobia, Situational Type","fear of one situation or one cluster."],["PTSD or Acute Stress Disorder","avoidance of trauma reminders."],["Major Depressive Disorder","housebound from apathy or fatigue."],["Psychotic disorder","avoidance from delusional fears."],["OCD","avoidance of obsession triggers."],["Separation Anxiety Disorder","fear of being away from attachment figures."],["Medical condition","realistic avoidance (for example, fainting with an arrhythmia)."]]},
{"roll":25,"id":"3.5.7","name":"Generalized Anxiety Disorder","group":"Anxiety Disorders","core":"Excessive, hard-to-control worry about many matters, 6 months or more, with three or more of restlessness, fatigue, poor concentration, irritability, muscle tension, and sleep problems.","diffs":[["Anxiety Disorder Due to Another Medical Condition","a medical cause (for example, pheochromocytoma) explains the anxiety."],["Substance/medication-induced","a substance explains the anxiety."],["Panic Disorder","worry only about panic attacks."],["Social Anxiety Disorder","worry only about social situations."],["Somatic Symptom or Illness Anxiety Disorder","worry only about health."],["Separation Anxiety Disorder","worry only about separation."],["PTSD or Acute Stress Disorder","anxiety only related to the trauma."],["Anorexia Nervosa","worry only about weight."],["OCD","intrusive, unwanted thoughts with compulsions."],["Body Dysmorphic Disorder","worry only about appearance."],["Adjustment Disorder with anxiety","response to a stressor that does not meet full criteria."],["Mood episode with anxious distress","anxiety only during the mood episode."],["Psychotic disorder","anxiety about delusional content."],["Normal anxiety","controllable, no impairment."]]},
{"roll":26,"id":"3.6.1","name":"Obsessive-Compulsive Disorder","group":"Obsessive-Compulsive and Related Disorders","core":"Obsessions and/or compulsions that take more than 1 hour per day or cause impairment.","diffs":[["Medical condition","a medical cause explains the symptoms."],["Substance/medication","a substance explains the symptoms."],["Hoarding Disorder","difficulty discarding without obsessions."],["Body Dysmorphic Disorder","concerns only about appearance."],["Eating disorder","concerns only about food and weight."],["Specific Phobia","fear of the object itself, not of an obsession trigger."],["Social Anxiety Disorder","reassurance seeking only about social fears."],["Trichotillomania or Excoriation Disorder","behavior only hair pulling or skin picking."],["Illness Anxiety Disorder","thoughts only about having a disease."],["Major Depressive Episode","mood-congruent rumination, not felt as intrusive."],["Generalized Anxiety Disorder","worries about real-life matters, without compulsions."],["Delusional Disorder","delusional conviction without obsessions and compulsions."],["Schizophrenia","other psychotic symptoms are present."],["Tic Disorders","simpler movements, not done to neutralize an obsession."],["Stereotypic Movement Disorder","simpler movements, not done to neutralize an obsession."],["Driven behaviors (gambling, substance use, paraphilias)","the activity gives pleasure."],["Obsessive-Compulsive Personality Disorder","perfectionism and control without true obsessions or compulsions."],["Normal superstitions","not time-consuming, no impairment."]]},
{"roll":27,"id":"3.6.2","name":"Body Dysmorphic Disorder","group":"Obsessive-Compulsive and Related Disorders","core":"Preoccupation with perceived appearance flaws that others cannot see or see as slight, with repetitive behaviors or mental acts.","diffs":[["Normal dissatisfaction, or a clearly visible defect","concern is not excessive."],["Anorexia or Bulimia Nervosa","concern only about body shape and weight."]]},
{"roll":28,"id":"3.6.3","name":"Hoarding Disorder","group":"Obsessive-Compulsive and Related Disorders","core":"Persistent difficulty discarding possessions because of a perceived need to save them. Clutter blocks the use of living areas.","diffs":[["Medical condition (for example, brain injury, stroke)","a medical cause explains the hoarding."],["Neurodegenerative Neurocognitive Disorder","gradual onset with self-neglect and squalor."],["Autism Spectrum Disorder","collection related to a fixed interest."],["OCD","accumulation from obsessions, felt as unwanted."],["Psychotic disorder","accumulation from a delusion."],["Major Depressive Episode","clutter from fatigue and low energy."],["Normal collecting","organized, without clutter or distress."]]},
{"roll":29,"id":"3.6.4","name":"Trichotillomania (Hair-Pulling Disorder)","group":"Obsessive-Compulsive and Related Disorders","core":"Recurrent hair pulling with hair loss, repeated attempts to stop, and distress or impairment.","diffs":[["Medical hair loss (alopecia)","a medical condition explains the hair loss."],["OCD","pulling is part of a ritual."],["Body Dysmorphic Disorder","hair removed because it looks ugly to the person."],["Psychotic disorder","pulling in response to a delusion or hallucination."],["Stereotypic Movement Disorder","other repetitive behaviors are also present."],["Nonsuicidal self-injury","no attempts to stop."],["Normal hair removal or twisting","cosmetic, no distress."]]},
{"roll":30,"id":"3.6.5","name":"Excoriation (Skin-Picking) Disorder","group":"Obsessive-Compulsive and Related Disorders","core":"Recurrent skin picking with lesions, repeated attempts to stop, and distress or impairment.","diffs":[["Dermatological condition (for example, scabies)","the skin condition explains the picking."],["Substance (for example, cocaine)","a substance explains the picking."],["OCD","lesions come from washing compulsions."],["Body Dysmorphic Disorder","picking to correct an appearance defect."],["Psychotic disorder","picking from a delusion of parasites or a tactile hallucination."],["Stereotypic Movement Disorder","other repetitive behaviors are also present."]]},
{"roll":31,"id":"3.7.1","name":"PTSD or Acute Stress Disorder","group":"Trauma- and Stressor-Related Disorders","members":["PTSD (more than 1 month)","Acute Stress Disorder (3 days to 1 month)"],"core":"Exposure to actual or threatened death, serious injury, or sexual violence. Then intrusion, avoidance, negative changes in thoughts and mood, and changes in arousal.","diffs":[["Adjustment Disorder","the stressor is not of this type, or the full pattern is absent."],["Prolonged Grief Disorder","yearning for the deceased and memories of many parts of the relationship."],["Other disorder after the stressor (for example, Major Depressive Disorder)","the symptoms fit that disorder."],["OCD","intrusive thoughts not related to a trauma."],["Panic Disorder","arousal only during panic attacks, without a trauma link."],["Generalized Anxiety Disorder","anxiety without a trauma link."],["Dissociative Disorders","dissociation without the full trauma syndrome."],["Psychotic disorder","hallucinations that are not trauma flashbacks."],["Traumatic brain injury","neurocognitive symptoms after head trauma. Both can be present."],["Malingering","feigned symptoms for an external reward."]]},
{"roll":32,"id":"3.7.2","name":"Adjustment Disorder","group":"Trauma- and Stressor-Related Disorders","core":"Emotional or behavioral symptoms within 3 months of an identifiable stressor. Distress out of proportion, or impairment. Criteria for another disorder are not met. Symptoms end within 6 months after the stressor ends.","diffs":[["Another specific mental disorder","its criteria are met."],["PTSD or Acute Stress Disorder","extreme stressor with the full pattern."],["Other Specified or Unspecified category","used only when no specific disorder, including Adjustment Disorder, fits."],["Psychological Factors Affecting Other Medical Conditions","psychological factors make a medical illness worse."],["Bereavement","an expected response to a death."],["Prolonged Grief Disorder","yearning for the deceased, 12 months or more."],["Normal stress reaction","expected and not impairing."]]},
{"roll":33,"id":"3.7.3","name":"Prolonged Grief Disorder","group":"Trauma- and Stressor-Related Disorders","core":"12 months or more after a death (6 months in children), intense yearning or preoccupation with the deceased, with three or more other grief symptoms and distress.","diffs":[["Normal grief","time-limited and within cultural norms."],["Major Depressive or Persistent Depressive Disorder","general low mood not focused on the loss."],["PTSD","intrusive memories of the death event with a here-and-now quality, without yearning."],["Adjustment Disorder","any stressor, and symptoms end within 6 months after it ends."],["Separation Anxiety Disorder","fear about separation from living attachment figures."]]},
{"roll":34,"id":"3.8.1","name":"Dissociative Amnesia","group":"Dissociative Disorders","core":"Inability to recall important personal information, usually of a traumatic or stressful nature. Other cognitive abilities are intact.","diffs":[["Neurocognitive Disorder due to a medical condition","broad cognitive deficits."],["Substance-induced blackouts","memory is not stored and usually does not return."],["Posttraumatic amnesia from brain injury","clear head injury with loss of consciousness."],["Dissociative Identity Disorder","identity discontinuities and many other dissociative symptoms."],["PTSD or Acute Stress Disorder","amnesia only for the traumatic event."],["Malingering or Factitious Disorder","feigned amnesia."],["Normal memory loss","expected for the context."]]},
{"roll":35,"id":"3.8.2","name":"Depersonalization/Derealization Disorder","group":"Dissociative Disorders","core":"Persistent or recurrent depersonalization and/or derealization, with intact reality testing.","diffs":[["Medical condition (for example, seizures)","a medical cause explains the symptoms."],["Substance intoxication or withdrawal (for example, cannabis, ketamine)","symptoms occur only with the substance."],["Dissociative Identity Disorder","identity discontinuities are present."],["Panic attacks","symptoms occur only during attacks and last minutes."],["PTSD or Acute Stress Disorder","trauma syndrome is present."],["Psychotic disorder","delusion that the person is dead or the world is not real."],["Major Depressive Disorder","numbness only during depressive episodes."],["Normal episodes","short, no impairment."]]},
{"roll":36,"id":"3.9.1","name":"Somatic Symptom Disorder","group":"Somatic Symptom and Related Disorders","core":"One or more distressing body symptoms, with excessive thoughts, feelings, or behaviors about them. 6 months or more.","diffs":[["Medical condition alone","no excessive response to the symptoms."],["Illness Anxiety Disorder","no or minimal body symptoms."],["Body Dysmorphic Disorder","concern about appearance."],["Functional Neurological Symptom Disorder","altered motor or sensory function that does not fit known disease."],["Generalized Anxiety Disorder","worries about many matters."],["Panic Disorder","body symptoms only during panic attacks."],["OCD","intrusive thoughts with compulsions."],["Depressive Disorders","body symptoms only during depression."],["Delusional Disorder, Somatic Type","belief held with delusional intensity."],["Factitious Disorder or Malingering","symptoms are produced on purpose."]]},
{"roll":37,"id":"3.9.2","name":"Illness Anxiety Disorder","group":"Somatic Symptom and Related Disorders","core":"Preoccupation with having or getting a serious illness, with no or minimal body symptoms and high health anxiety. 6 months or more.","diffs":[["Concern about a real illness","concern is proportionate."],["Somatic Symptom Disorder","significant body symptoms are present."],["Specific Phobia of disease","fear of getting a disease, not of having it."],["Generalized Anxiety Disorder","health is one of many worries."],["Panic Disorder","acute, episodic health fear during attacks."],["OCD","fear of a future disease, with other obsessions."],["Body Dysmorphic Disorder","concern only about appearance."],["Adjustment Disorder","time-limited response to a stressor."],["Major Depressive Disorder","health worry only during depressive episodes."],["Psychotic disorder","somatic delusions of fixed intensity."]]},
{"roll":38,"id":"3.9.3","name":"Functional Neurological Symptom Disorder (Conversion Disorder)","group":"Somatic Symptom and Related Disorders","core":"Altered voluntary motor or sensory function. Clinical findings show the symptoms do not fit a known neurological or medical condition.","diffs":[["Hidden neurological or medical condition, or substance","fully explains the deficit."],["Somatic Symptom Disorder","excessive thoughts about symptoms, no need for incompatibility."],["Depressive Disorders","general heaviness of the limbs with depressive symptoms."],["Dissociative Disorders","disruptions of memory or identity."],["Factitious Disorder or Malingering","symptoms are produced on purpose."]]},
{"roll":39,"id":"3.9.4","name":"Psychological Factors Affecting Other Medical Conditions","group":"Somatic Symptom and Related Disorders","core":"Psychological or behavioral factors make a medical condition worse, and these factors do not meet criteria for a mental disorder.","diffs":[["Mental disorder due to a medical condition","the medical condition causes the psychiatric symptoms."],["Adjustment Disorder","the medical illness is a stressor that causes distress."],["Mental disorder that worsens a medical illness (for example, Alcohol Use Disorder with cirrhosis)","full criteria for the mental disorder are met."],["Somatic Symptom Disorder","focus on excessive thoughts and behaviors about symptoms."],["Illness Anxiety Disorder","focus on health anxiety itself."]]},
{"roll":40,"id":"3.9.5","name":"Factitious Disorder","group":"Somatic Symptom and Related Disorders","members":["Factitious Disorder Imposed on Self","Factitious Disorder Imposed on Another"],"core":"Falsification or induction of signs or symptoms, with deception, without an obvious external reward.","diffs":[["Somatic Symptom Disorder","no evidence of deception."],["Malingering","an external reward (for example, money, time off work)."],["Functional Neurological Symptom Disorder","no evidence of deception."],["Borderline Personality Disorder","self-harm without deception."],["Caregiver lying about abuse injuries (only vs. Imposed on Another)","lies only to avoid legal liability."]]},
{"roll":41,"id":"3.10.1","name":"Avoidant/Restrictive Food Intake Disorder","group":"Feeding and Eating Disorders","core":"Avoidant or restrictive eating, with weight loss, nutritional deficiency, dependence on supplements or tube feeding, or psychosocial interference. No body-image disturbance.","diffs":[["Medical condition","the illness explains the restriction."],["Neurological, structural, or congenital feeding problem","the physical problem explains the restriction."],["Reactive Attachment Disorder","disturbance of the caregiver relationship."],["Autism Spectrum Disorder","rigid eating without significant weight loss or deficiency."],["Specific Phobia of choking or vomiting","avoidance of these situations is the main problem."],["Anorexia Nervosa","fear of weight gain and body-image disturbance."],["Major Depressive Disorder","appetite loss that stops when the depression stops."],["Psychotic disorder","food avoidance from a delusion."]]},
{"roll":42,"id":"3.10.2","name":"Anorexia Nervosa","group":"Feeding and Eating Disorders","core":"Restriction that leads to significantly low weight, intense fear of weight gain or behavior that prevents gain, and disturbed experience of body weight or shape.","diffs":[["Medical condition","weight loss without body-image disturbance."],["Substance Use Disorder","low weight without fear of weight gain."],["Bulimia Nervosa","weight is normal or above."],["ARFID","no fear of weight gain."],["Depressive weight loss","no wish to lose weight."],["Schizophrenia","odd eating from delusions."],["OCD","obsessions about matters other than food."],["Social Anxiety Disorder","social fears beyond eating."],["Body Dysmorphic Disorder","concerns beyond weight and shape."]]},
{"roll":43,"id":"3.10.3","name":"Bulimia Nervosa","group":"Feeding and Eating Disorders","core":"Recurrent binge eating and compensatory behavior, both once a week or more for 3 months. Self-worth depends on shape and weight. Not only during Anorexia Nervosa.","diffs":[["Medical or substance cause of vomiting or diarrhea","the cause is physiological."],["Anorexia Nervosa, Binge-Eating/Purging Type","weight is significantly low."],["Binge-Eating Disorder","no regular compensatory behavior."],["Kleine-Levin syndrome","overeating without concern about shape or weight."],["Major Depressive Episode with atypical features","overeating without binges or compensation."],["Borderline Personality Disorder","binge eating without compensatory behavior."]]},
{"roll":44,"id":"3.10.4","name":"Binge-Eating Disorder","group":"Feeding and Eating Disorders","core":"Recurrent binges with loss of control and marked distress, once a week or more for 3 months, without regular compensatory behavior.","diffs":[["Bulimia Nervosa","regular compensatory behavior."],["Obesity alone","no binge pattern."],["Major Depressive Episode with atypical features","overeating without loss of control."],["Borderline Personality Disorder","binge eating as one of many impulsive behaviors."]]},
{"roll":45,"id":"3.11.1","name":"Insomnia Disorder","group":"Sleep-Wake Disorders","core":"Dissatisfaction with sleep, with difficulty falling asleep, staying asleep, or early waking. Three nights per week or more for 3 months or more, despite enough opportunity to sleep.","diffs":[["Short sleeper","no daytime symptoms."],["Sleep deprivation","no opportunity to sleep."],["Circadian Rhythm Sleep-Wake Disorder","normal sleep on the person's own schedule, or recent shift work."],["Restless Legs Syndrome","urge to move the legs."],["Breathing-Related Sleep Disorder","loud snoring and breathing pauses."],["Narcolepsy","cataplexy and sleep attacks."],["Parasomnias","sleep events are the main problem."],["Insomnia with another disorder","the other disorder does not fully explain it (use a specifier)."],["Substance/medication-induced","insomnia only during use."]]},
{"roll":46,"id":"3.11.2","name":"Hypersomnolence Disorder","group":"Sleep-Wake Disorders","core":"Excessive sleepiness despite 7 hours or more of main sleep, with naps or lapses into sleep, more than 9 hours of unrefreshing sleep, or difficulty waking. Three times per week or more for 3 months or more.","diffs":[["Normal long sleeper","refreshed after enough sleep."],["Insufficient sleep","less than 7 hours per night."],["Insomnia Disorder","fatigue from poor sleep."],["Narcolepsy","cataplexy and specific REM sleep findings."],["Breathing-Related Sleep Disorder","apneas on a sleep study."],["Circadian Rhythm Sleep-Wake Disorder","abnormal sleep-wake schedule."],["Parasomnias","sleepiness from night events."],["Hypersomnolence with another disorder","the other disorder does not fully explain it."],["Substance/medication-induced","sleepiness only during use."]]},
{"roll":48,"id":"3.13.1","name":"Gender Dysphoria","group":"Gender Dysphoria","core":"Marked incongruence between experienced gender and assigned gender, 6 months or more, with distress or impairment.","diffs":[["Gender nonconformity","no distress and no wish to be another gender."],["Transvestic Disorder","sexual arousal from cross-dressing without gender incongruence."],["Body Dysmorphic Disorder","a body part is seen as ugly, not as the wrong gender."],["Psychotic disorder","other psychotic symptoms are present."]]},
{"roll":49,"id":"3.14.1","name":"Oppositional Defiant Disorder","group":"Disruptive, Impulse-Control, and Conduct Disorders","core":"Angry or irritable mood, argumentative or defiant behavior, or vindictiveness. Four or more symptoms for 6 months or more, with at least one person who is not a sibling.","diffs":[["Normal developmental opposition","not persistent or not significant."],["Adjustment Disorder with disturbance of conduct","time-limited response to a stressor."],["Conduct Disorder","aggression, destruction, or theft."],["ADHD","opposition only to tasks that need sustained effort."],["Disruptive Mood Dysregulation Disorder","more frequent and severe outbursts."],["Intermittent Explosive Disorder","serious physical or verbal aggression."],["Mood or psychotic disorder","opposition only during the mood disturbance or psychosis."],["Intellectual Developmental Disorder","opposition matches the mental age."],["Language Disorder","failure to follow directions from poor comprehension."],["Selective Mutism","silence from fear, not defiance."]]},
{"roll":50,"id":"3.14.2","name":"Intermittent Explosive Disorder","group":"Disruptive, Impulse-Control, and Conduct Disorders","core":"Recurrent impulsive outbursts out of proportion to the cause. Verbal or minor physical aggression twice a week for 3 months, or three damaging outbursts in 12 months. Age 6 or more.","diffs":[["Substance intoxication or withdrawal","outbursts only with the substance."],["Delirium","outbursts only during delirium."],["Neurocognitive Disorder with behavioral disturbance","aggression only with cognitive decline."],["Personality Change Due to Another Medical Condition, Aggressive Type","a medical cause is present."],["Disruptive Mood Dysregulation Disorder","persistent irritable mood between outbursts."],["Antisocial or Borderline Personality Disorder","long-standing personality pattern explains the outbursts."],["ADHD, Conduct Disorder, or ODD","aggression fits that disorder (planned aggression in Conduct Disorder)."],["Other mental disorder (for example, mania, schizophrenia)","aggression only during episodes."],["Aggression without a disorder","motivated by gain, revenge, or belief."]]},
{"roll":51,"id":"3.14.3","name":"Conduct Disorder","group":"Disruptive, Impulse-Control, and Conduct Disorders","core":"Three or more of 15 behaviors in 12 months: aggression, destruction of property, deceit or theft, or serious rule violations.","diffs":[["Oppositional Defiant Disorder","no aggression, destruction, or theft."],["ADHD","disruptive behavior that does not violate rights or norms."],["Mood disorder","conduct problems only during mood disturbance."],["Intermittent Explosive Disorder","only impulsive, unplanned aggression."],["Psychotic disorder","antisocial acts only in response to delusions or hallucinations."],["Adjustment Disorder with disturbance of conduct","time-limited response to a stressor."],["Child or adolescent antisocial behavior","isolated acts below the threshold."],["Antisocial Personality Disorder","age 18 or more."]]},
{"roll":52,"id":"3.15.1","name":"Substance Use Disorders","group":"Substance-Related and Addictive Disorders","core":"Problematic pattern of substance use, with two or more of 11 criteria in 12 months.","diffs":[["Nonpathological use","no significant negative consequences."],["Substance-induced mental disorder","a brain syndrome from the substance (both are common together)."],["Conduct Disorder or Antisocial Personality Disorder","a broad antisocial pattern (often co-occur)."],["Substance use only during manic episodes","manic symptoms continue without the substance."]]},
{"roll":53,"id":"3.15.2","name":"Gambling Disorder","group":"Substance-Related and Addictive Disorders","core":"Persistent, recurrent problem gambling, with four or more of nine criteria in 12 months.","diffs":[["Professional gambling","disciplined and limited risk, as a source of income."],["Social gambling","limited time and risk, with friends."],["Manic Episode","manic symptoms also occur without gambling."],["Internet Gaming Disorder","no money is wagered."]]},
{"roll":54,"id":"3.16.1","name":"Delirium","group":"Neurocognitive Disorders","core":"Acute disturbance of attention and awareness that fluctuates during the day, with other cognitive changes, caused by a medical condition or substance.","diffs":[["Major or Mild Neurocognitive Disorder","stable or gradual course, attention intact."],["Substance intoxication or withdrawal","attention problems do not dominate."],["Psychotic disorder due to a substance or medical condition","attention and awareness intact."],["Primary psychotic or mood disorder","no medical cause, attention intact."]]},
{"roll":55,"id":"3.16.2","name":"Major or Mild Neurocognitive Disorder","group":"Neurocognitive Disorders","members":["Major (decline interferes with independence)","Mild (decline does not interfere with independence)"],"core":"Decline from a previous level in one or more cognitive domains, caused by a medical condition or substance.","diffs":[["Delirium","acute onset, fluctuating attention."],["Substance intoxication or withdrawal","impairment stops when acute effects stop."],["Intellectual Developmental Disorder","deficit from development, not a decline."],["Schizophrenia","earlier onset, psychotic symptoms."],["Dissociative Amnesia","limited memory loss for traumatic events."],["Major Depressive Disorder","deficits improve when depression stops."],["Bipolar I Disorder","earlier onset, mood episodes."],["Normal aging","decline expected for age."]]},
{"roll":56,"id":"3.17.1","name":"Paranoid Personality Disorder","group":"Personality Disorders","core":"Pervasive distrust and suspicion of others' motives, four or more of seven criteria, from early adulthood.","diffs":[["Psychotic disorder","persistent persecutory delusions."],["Personality Change Due to Another Medical Condition, Paranoid Type","a medical cause."],["Schizotypal Personality Disorder","magical thinking and odd perceptions."],["Schizoid Personality Disorder","no interest in relationships, not distrust."],["Borderline Personality Disorder","short paranoia under stress of abandonment."],["Avoidant Personality Disorder","fear of embarrassment."],["Narcissistic Personality Disorder","fear that flaws will be seen."]]},
{"roll":57,"id":"3.17.2","name":"Schizoid Personality Disorder","group":"Personality Disorders","core":"Detachment from relationships and restricted emotional expression, four or more of seven criteria.","diffs":[["Schizophrenia","positive psychotic symptoms."],["Autism Spectrum Disorder","restricted, repetitive behaviors."],["Personality Change Due to Another Medical Condition, Apathetic Type","a medical cause."],["Schizotypal Personality Disorder","perceptual and cognitive distortions."],["Avoidant Personality Disorder","wants relationships but fears rejection."],["Obsessive-Compulsive Personality Disorder","detachment from devotion to work."]]},
{"roll":58,"id":"3.17.3","name":"Schizotypal Personality Disorder","group":"Personality Disorders","core":"Discomfort in close relationships, cognitive or perceptual distortions, and eccentric behavior, five or more of nine criteria.","diffs":[["Psychotic disorder","periods of full psychotic symptoms."],["Autism Spectrum Disorder","restricted, repetitive behaviors."],["Personality Change Due to Another Medical Condition, Paranoid Type","a medical cause."],["Paranoid Personality Disorder","no perceptual distortions or eccentricity."],["Schizoid Personality Disorder","no perceptual distortions or eccentricity."],["Avoidant Personality Disorder","wants relationships but fears rejection."],["Narcissistic Personality Disorder","withdrawal from fear that flaws will be seen."],["Borderline Personality Disorder","short, stress-linked symptoms with mood shifts."],["Transient adolescent traits","from temporary emotional turmoil."]]},
{"roll":59,"id":"3.17.4","name":"Antisocial Personality Disorder","group":"Personality Disorders","core":"Disregard for others' rights since age 15, three or more of seven criteria, age 18 or more, with Conduct Disorder before age 15.","diffs":[["Antisocial acts only with substance use","no pattern from childhood."],["Antisocial acts only during manic episodes","from mania, no prior Conduct Disorder."],["Conduct Disorder","age under 18."],["Narcissistic Personality Disorder","no impulsivity or aggression, no Conduct Disorder."],["Histrionic Personality Disorder","no deceit or recklessness, no Conduct Disorder."],["Borderline Personality Disorder","no criminality, no Conduct Disorder."],["Paranoid Personality Disorder","acts from revenge."],["Criminal behavior without a disorder","for gain, without a lifelong pattern."]]},
{"roll":60,"id":"3.17.5","name":"Borderline Personality Disorder","group":"Personality Disorders","core":"Instability of relationships, self-image, and mood, with marked impulsivity, five or more of nine criteria.","diffs":[["Histrionic Personality Disorder","no self-destructiveness or chronic emptiness."],["Schizotypal Personality Disorder","paranoia less reactive to relationships."],["Paranoid or Narcissistic Personality Disorder","stable self-image, little impulsivity."],["Antisocial Personality Disorder","manipulation for gain, not for nurturance."],["Dependent Personality Disorder","responds to abandonment with submission."],["Personality Change Due to Another Medical Condition, Labile Type","a medical cause."]]},
{"roll":61,"id":"3.17.6","name":"Histrionic Personality Disorder","group":"Personality Disorders","core":"Excessive emotionality and attention seeking, five or more of eight criteria.","diffs":[["Borderline Personality Disorder","self-destructiveness and identity disturbance."],["Antisocial Personality Disorder","manipulation for gain."],["Narcissistic Personality Disorder","wants praise for superiority."],["Dependent Personality Disorder","no flamboyant emotions."],["Personality Change Due to Another Medical Condition, Disinhibited Type","a medical cause."]]},
{"roll":62,"id":"3.17.7","name":"Narcissistic Personality Disorder","group":"Personality Disorders","core":"Grandiosity, need for admiration, and lack of empathy, five or more of nine criteria.","diffs":[["Histrionic Personality Disorder","needs approval, not admiration."],["Antisocial Personality Disorder","impulsivity, aggression, deceit."],["Borderline Personality Disorder","unstable self-image and fear of abandonment."],["Obsessive-Compulsive Personality Disorder","strives for perfection, does not believe it is achieved."],["Schizotypal or Paranoid Personality Disorder","paranoid ideation."],["Manic or Hypomanic Episode","grandiosity only during the episode."],["Personality Change Due to Another Medical Condition","a medical cause."]]},
{"roll":63,"id":"3.17.8","name":"Avoidant Personality Disorder","group":"Personality Disorders","core":"Social inhibition, feelings of inadequacy, and sensitivity to criticism, four or more of seven criteria.","diffs":[["Agoraphobia","avoidance of places where escape is difficult."],["Dependent Personality Disorder","focus on being taken care of."],["Schizoid or Schizotypal Personality Disorder","content to be alone."],["Paranoid Personality Disorder","fear that information will be used against the person."],["Personality Change Due to Another Medical Condition","a medical cause."]]},
{"roll":64,"id":"3.17.9","name":"Dependent Personality Disorder","group":"Personality Disorders","core":"Excessive need to be taken care of, with submissive, clinging behavior and fear of separation, five or more of eight criteria.","diffs":[["Separation Anxiety Disorder","fear of physical separation from specific figures."],["Dependency from another disorder or medical condition","from real impairment."],["Borderline Personality Disorder","rage and emptiness when abandonment is feared."],["Histrionic Personality Disorder","flamboyant demands for attention."],["Avoidant Personality Disorder","withdrawal until acceptance is certain."],["Personality Change Due to Another Medical Condition","a medical cause."]]},
{"roll":65,"id":"3.17.10","name":"Obsessive-Compulsive Personality Disorder","group":"Personality Disorders","core":"Preoccupation with order, perfectionism, and control, at the cost of flexibility, four or more of eight criteria.","diffs":[["OCD","true obsessions or compulsions."],["Hoarding Disorder","clutter dominates the clinical picture."],["Narcissistic Personality Disorder","believes perfection is already achieved."],["Antisocial Personality Disorder","spends freely on self."],["Schizoid Personality Disorder","no capacity for intimacy."],["Personality Change Due to Another Medical Condition","a medical cause."]]},
{"roll":66,"id":"3.17.11","name":"Personality Change Due to Another Medical Condition","group":"Personality Disorders","core":"Persistent change from the previous personality, with evidence of a medical cause.","diffs":[["Neurocognitive Disorder","cognitive decline is present."],["Other mental disorder due to a medical condition","other prominent symptoms (for example, irritable mood)."],["Substance Use Disorder","change stops in remission."],["Other mental disorder (for example, schizophrenia)","no medical cause."],["Personality Disorder","onset by early adulthood, no medical cause."]]}];
